def terme_b_conv(k, n, i):
    """Construction terme a terme avec saut Zeta en position 6 (Section XIV.4)."""
    if k < 2 or n < 1 or i < 1 or i > n:
        return 0
    if n <= 7:
        return terme_a_conv(k, n, i)
    if i <= 5:
        return k**i
    elif i == 6:
        return k**7
    elif i <= n - 2:
        return k**(i + 1)
    elif i == n - 1:
        return k**n - k**(n - 2)
    else:
        return k**(n + 1) - k**(n - 1)
